// Voice-over: one audio clip per narration line (the `subtitles` of each
// scene). Clips are generated by scripts/generate-voiceover.ts and listed in
// public/voiceover/manifest.json. This file is shared by the video and the
// generator script, so it must not import anything React / Remotion.
import type { VideoContent, VoiceClip } from "./schema";
import { buildTimeline } from "./timeline";

export const MANIFEST_PATH = "voiceover/manifest.json";

export type ManifestEntry = {
  file: string; // relative to public/
  text: string;
  /** Text actually sent to the voice, when a pronunciation fix changed it. */
  spoken?: string;
  durationInSeconds: number;
  provider: "elevenlabs" | "mock" | "recording";
  voiceId?: string;
  modelId?: string;
};

// videoId → line key (e.g. "tip2-1") → clip
export type VoiceManifest = Record<string, Record<string, ManifestEntry>>;

export type VoiceLine = {
  key: string;
  sceneIndex: number;
  lineIndex: number;
  text: string; // shown in the subtitles
  spoken: string; // read by the voice (text + pronunciation fixes)
};

// Replaces every word listed in voiceover.pronunciations by the spelling the
// voice should read.
export const applyPronunciations = (text: string, fixes: Record<string, string>) =>
  Object.entries(fixes).reduce(
    (result, [word, spoken]) => (word ? result.split(word).join(spoken) : result),
    text,
  );

const sceneNames = (content: VideoContent) => [
  "intro",
  ...content.tips.map((_, i) => `tip${i + 1}`),
  "outro",
];

const sceneSubtitles = (content: VideoContent) => [
  content.intro.subtitles,
  ...content.tips.map((t) => t.subtitles),
  content.outro.subtitles,
];

export const getVoiceLines = (content: VideoContent): VoiceLine[] => {
  const names = sceneNames(content);
  return sceneSubtitles(content).flatMap((lines, sceneIndex) =>
    lines
      .map((text, lineIndex) => ({
        key: `${names[sceneIndex]}-${lineIndex}`,
        sceneIndex,
        lineIndex,
        text: text.trim(),
        spoken: applyPronunciations(text.trim(), content.voiceover.pronunciations),
      }))
      .filter((line) => line.text.length > 0),
  );
};

const withSceneDurations = (content: VideoContent, durations: number[]): VideoContent => ({
  ...content,
  intro: { ...content.intro, durationInFrames: durations[0] },
  tips: content.tips.map((tip, i) => ({ ...tip, durationInFrames: durations[i + 1] })),
  outro: { ...content.outro, durationInFrames: durations[durations.length - 1] },
});

const TAIL = 6; // frames kept after the last line of a scene

// Frames between the start of a scene and its first narration line.
const leadIn = (sceneIndex: number, transition: number) =>
  sceneIndex === 0 ? 8 : Math.ceil(transition / 2) + 4;

type VoiceSettings = VideoContent["voiceover"];

/**
 * Places the voice clips of each scene. A clip is used only if the manifest
 * text matches the current narration line (edited text = clip ignored until
 * it is regenerated). Scenes get longer if their narration needs more time.
 * Shared by the classic videos and the story reels.
 * Returns the new scene durations and the clips with their offset in their
 * scene (frames from the scene start).
 */
export const layoutVoice = (
  lines: VoiceLine[],
  configured: number[],
  transition: number,
  voice: VoiceSettings,
  entries: Record<string, ManifestEntry>,
  fps: number,
) => {
  const clips: (Omit<VoiceClip, "from"> & { offset: number })[] = [];
  const durations = configured.map((duration, sceneIndex) => {
    let cursor = leadIn(sceneIndex, transition);
    let hasClip = false;
    for (const line of lines.filter((l) => l.sceneIndex === sceneIndex)) {
      const entry = entries[line.key];
      // Ignore clips made for an older text or pronunciation.
      if (
        !entry ||
        entry.text.trim() !== line.text ||
        (entry.spoken ?? entry.text).trim() !== line.spoken
      ) {
        continue;
      }
      const durationInFrames = Math.ceil((entry.durationInSeconds / voice.playbackRate) * fps);
      clips.push({
        sceneIndex,
        lineIndex: line.lineIndex,
        src: entry.file,
        durationInFrames,
        offset: cursor,
      });
      cursor += durationInFrames + voice.gapInFrames;
      hasClip = true;
    }
    if (!hasClip) {
      return duration;
    }
    const isLast = sceneIndex === configured.length - 1;
    const needed = cursor - voice.gapInFrames + TAIL + (isLast ? 0 : Math.ceil(transition / 2));
    return Math.max(duration, needed);
  });
  return { durations, clips };
};

/** Classic videos (intro, tips, outro): see layoutVoice. */
export const applyVoiceover = (
  content: VideoContent,
  entries: Record<string, ManifestEntry> | undefined,
  fps: number,
): VideoContent => {
  if (!content.voiceover.enabled || !entries) {
    return { ...content, voiceClips: [] };
  }
  const configured = [
    content.intro.durationInFrames,
    ...content.tips.map((t) => t.durationInFrames),
    content.outro.durationInFrames,
  ];
  const { durations, clips } = layoutVoice(
    getVoiceLines(content),
    configured,
    content.transitionDurationInFrames,
    content.voiceover,
    entries,
    fps,
  );
  const adjusted = withSceneDurations(content, durations);
  const timeline = buildTimeline(adjusted);
  const voiceClips = clips.map(({ offset, ...clip }) => ({
    ...clip,
    from: timeline[clip.sceneIndex].from + offset,
  }));
  return { ...adjusted, voiceClips };
};
